  p_OutputType_d022db6f3921 := 'object';
  p_OutputExample_d022db6f3921 := '{"taskComplete":false,"message":"I''ve put together a plan to predict which active members are at risk of not renewing in the next 90 days. We''ll train and compare a few models and judge them by AUC (how well they rank who''s most at risk). One heads-up: the Data Scout flagged ''last_payment_date'' as a leakage risk, so we''ll exclude it. Want me to go ahead and run the experiments, or adjust anything first?","reasoning":"Goal, data, and experiments are defined and leakage has been addressed. Presenting the plan for explicit approval before execution.","responseForm":{"title":"Ready to run the experiments?","submitLabel":"Continue","questions":[{"id":"planDecision","label":"How would you like to proceed?","required":true,"type":{"type":"buttongroup","options":[{"value":"approve_and_run_it","label":"Approve and run it"},{"value":"change_the_goal","label":"Change the goal"},{"value":"change_the_data_features","label":"Change the data/features"},{"value":"change_the_experiments_or_budget","label":"Change the experiments or budget"}]}}]},"nextStep":{"type":"Chat"}}';
