-- Save MJ: Test Types (core SP call only)
DO $mj$
DECLARE
  p_ID_402b127a07f5 UUID;
  p_Name_402b127a07f5 VARCHAR(100);
  p_Description_402b127a07f5 TEXT;
  p_DriverClass_402b127a07f5 VARCHAR(255);
  p_Status_402b127a07f5 VARCHAR(20);
  p_VariablesSchema_402b127a07f5 TEXT;
BEGIN
  p_ID_402b127a07f5 := '7CAED395-0BEF-437E-A343-AC0841D377DA';
  p_Name_402b127a07f5 := 'Prompt Eval';
  p_Description_402b127a07f5 := 'Evaluates a SINGLE model decision from frozen mid-loop state. No action ever executes — the runner returns the model reply and deterministic oracles read the decision off whichever channel it used (envelope or native tool calls). This is the corpus workhorse for the envelope baseline and the native comparison; loop-level cases use Agent Eval instead.';
  p_DriverClass_402b127a07f5 := 'PromptEvalDriver';
  p_Status_402b127a07f5 := 'Active';
  p_VariablesSchema_402b127a07f5 := '{"schemaVersion":"1.0","variables":[{"name":"ToolCallingMode","displayName":"Tool Calling Mode","description":"Which encoding the cell exercises. ''envelope'' is the baseline — today''s path, no tools declared. ''native'' declares the agent''s actions as provider tools; the corpus case and its expectation are IDENTICAL either way, which is what makes the two directly comparable.","dataType":"string","valueSource":"static","possibleValues":[{"value":"envelope","label":"Envelope","description":"JSON envelope only — the baseline"},{"value":"native","label":"Native tools","description":"Actions declared as provider tools"}],"defaultValue":"envelope","required":false},{"name":"ToolChoice","displayName":"Tool Choice","description":"Forcing policy for native cells. Ignored in envelope mode. NOTE: forced choice (''required''/named) combined with JSON response format is a hard 400 on every current Gemini model.","dataType":"string","valueSource":"static","possibleValues":[{"value":"auto","label":"Auto","description":"The model decides"},{"value":"none","label":"None","description":"Tools declared but calling forbidden"},{"value":"required","label":"Required","description":"The model must call some tool"}],"defaultValue":"auto","required":false},{"name":"Model","displayName":"Model","description":"Pins the (model, vendor) pair for this cell. Every AIModelVendor pair is its own cell by design — inference-provider behavior is exactly what the vendor-level capability flags exist to capture.","dataType":"string","valueSource":"freeform","required":false},{"name":"ResponseFormat","displayName":"Response Format","description":"The prompt''s response format for this cell. Crosses with ToolCallingMode to cover the JSON-mode interaction the provider probe measured.","dataType":"string","valueSource":"static","possibleValues":[{"value":"Any","label":"Any","description":"No provider-level format constraint"},{"value":"JSON","label":"JSON","description":"Provider JSON mode"}],"required":false}]}';
  IF EXISTS (
    SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = '__mj' AND p.proname = 'spCreateTestType'
       AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype
  ) THEN
    PERFORM __mj."spCreateTestType"(p_data := jsonb_build_object(
    'ID', p_ID_402b127a07f5,
    'Name', p_Name_402b127a07f5,
    'Description', p_Description_402b127a07f5,
    'DriverClass', p_DriverClass_402b127a07f5,
    'Status', p_Status_402b127a07f5,
    'VariablesSchema', p_VariablesSchema_402b127a07f5
  ));
  ELSE
    PERFORM __mj."spCreateTestType"(p_ID := p_ID_402b127a07f5, p_Name := p_Name_402b127a07f5, p_Description := p_Description_402b127a07f5, p_DriverClass := p_DriverClass_402b127a07f5, p_Status := p_Status_402b127a07f5, p_VariablesSchema := p_VariablesSchema_402b127a07f5);
  END IF;
END $mj$;

