BEGIN
  p_DisplayName_120767e5de97 := 'Model Configuration';
  p_Description_120767e5de97 := 'Type-wide default of the per-modality model-configuration bag (JSON, IAIModelConfiguration shape: LLM / Realtime / Vision / Audio sections). Base layer of the ModelConfiguration cascade — AIModel and AIModelVendor rows inherit from it per key and may override. NULL = contributes nothing.';
  p_AutoUpdateDescription_120767e5de97 := TRUE;
  p_IsPrimaryKey_120767e5de97 := FALSE;
  p_IsUnique_120767e5de97 := FALSE;
  p_Category_120767e5de97 := 'Model Information';
